#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netinet/udp.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

/*
#ifndef UDP_GRO
#define UDP_GRO 104
#endif

#ifndef UDP_ENCAP
#define UDP_ENCAP 100
#endif
*/
// Hardcoding values as headers might be old
#define MY_UDP_ENCAP 100
#define MY_UDP_GRO 104

#define UDP_ENCAP_ESPINUDP 2

int main() {
    int fd = socket(AF_INET6, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    int val;

    // UDP_GRO
    val = 1;
    if (setsockopt(fd, IPPROTO_UDP, MY_UDP_GRO, &val, sizeof(val)) < 0) {
        perror("setsockopt UDP_GRO");
    } else {
        printf("UDP_GRO set\n");
    }

    // UDP_ENCAP
    val = UDP_ENCAP_ESPINUDP;
    if (setsockopt(fd, IPPROTO_UDP, MY_UDP_ENCAP, &val, sizeof(val)) < 0) {
        perror("setsockopt UDP_ENCAP");
    } else {
        printf("UDP_ENCAP set\n");
    }

    close(fd);
    printf("Socket closed\n");
    return 0;
}

